(958761, 111750, 27375, '<td valign="top">cool mailbox, looks a little like a crown royal sign on it.</td>', 'cool mailbox, looks a little like a crown royal sign on it.', '2004-10-14 01:17:41.000000', NULL, 1),
(958764, 111259, 27375, '<td valign="top">hey, how did you get apicture of my family   :)  were all lost.      this is funny</td>', 'hey, how did you get apicture of my family   :)  were all lost.      this is funny', '2004-10-14 01:18:49.000000', NULL, 1),
