(958766, 111184, 24983, '<td valign="top">this is a very good interpretation</td>', 'this is a very good interpretation', '2004-10-14 01:19:15.000000', NULL, 1),
(958768, 112422, 10339, '<td valign="top">Of all the cans and strings in this challenge - this has the most interesting lighting. Well done.</td>', 'Of all the cans and strings in this challenge - this has the most interesting lighting. Well done.', '2004-10-14 01:20:04.000000', NULL, 1),
(958770, 112296, 10339, '<td valign="top">I really like the composition and the concepts that you have captured here. The sepia tone works well for this. IMO - it would be better if the camera were in focus and not the background.</td>', 'I really like the composition and the concepts that you have captured here. The sepia tone works well for this. IMO - it would be better if the camera were in focus and not the background.', '2004-10-14 01:21:47.000000', NULL, 1),
(958771, 112190, 10339, '<td valign="top">Nicely done. I love the colors of the sky and the sun on the shirt.</td>', 'Nicely done. I love the colors of the sky and the sun on the shirt.', '2004-10-14 01:22:48.000000', NULL, 1),
(958773, 111660, 27375, '<td valign="top">i really like how you made the headline on the paper your title, if you hadnt have done that i most likely would not have payed as much attention to it. the more i looked at it the more i liked it. its not a pretty porch, its real life. good angle, good compostion.  i like this</td>', 'i really like how you made the headline on the paper your title, if you hadnt have done that i most likely would not have payed as much attention to it. the more i looked at it the more i liked it. its not a pretty porch, its real life. good angle, good compostion.  i like this', '2004-10-14 01:23:35.000000', NULL, 1),
(958777, 111600, 27375, '<td valign="top">interesting picture, i cant tell if this is a curved tunnel or the light source is comeing from an angle<br/>also the pink writing on the top mid area that starts with a D, looks as if it is painted on the picture and not the wall, thats strange  :)   but it makes for an interesting picture</td>', 'interesting picture, i cant tell if this is a curved tunnel or the light source is comeing from an anglealso the pink writing on the top mid area that starts with a D, looks as if it is painted on the picture and not the wall, thats strange  :)   but it makes for an interesting picture', '2004-10-14 01:27:24.000000', NULL, 1),
(958778, 112182, 24511, '<td valign="top">Architecture comes to mind rather than communication in prayer when I see this photo.  I would love a challenge with historical buildings.  The lighting could use light and shadow movement.  I like the angle and would like to see the point of the rooftop.  Thanks for sharing.</td>', 'Architecture comes to mind rather than communication in prayer when I see this photo.  I would love a challenge with historical buildings.  The lighting could use light and shadow movement.  I like the angle and would like to see the point of the rooftop.  Thanks for sharing.', '2004-10-14 01:30:13.000000', NULL, 1),
(958805, 112169, 27240, '<td valign="top">Good color, interesting angle, sincere poses.  Nice work!</td>', 'Good color, interesting angle, sincere poses.  Nice work!', '2004-10-14 01:46:08.000000', NULL, 1),
(958806, 112003, 27240, '<td valign="top">Great composition.</td>', 'Great composition.', '2004-10-14 01:46:46.000000', NULL, 1),
(958808, 112297, 27240, '<td valign="top">That''s a power line and a transformer, not a phone line.<br/> <br/>Nice photo, though.</td>', 'That''s a power line and a transformer, not a phone line. Nice photo, though.', '2004-10-14 01:47:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(958810, 112359, 27240, '<td valign="top">Clever pun, but the photo doesn''t convey "communication" in any real sense.  I don''t think the title of a photo should be its only visible connection to the theme.</td>', 'Clever pun, but the photo doesn''t convey "communication" in any real sense.  I don''t think the title of a photo should be its only visible connection to the theme.', '2004-10-14 01:49:28.000000', NULL, 1),
(958812, 112258, 27240, '<td valign="top">Fits the theme, but the photo is pretty boring.  Seems out of focus, too.</td>', 'Fits the theme, but the photo is pretty boring.  Seems out of focus, too.', '2004-10-14 01:50:36.000000', NULL, 1),
(958826, 112351, 24511, '<td valign="top">Antique road show here we come.  I love antiques.  What did they call these keyboard thingies again?  I like the angle and the introduction of a light source to cast shadow.  Thanks for photo.</td>', 'Antique road show here we come.  I love antiques.  What did they call these keyboard thingies again?  I like the angle and the introduction of a light source to cast shadow.  Thanks for photo.', '2004-10-14 02:04:13.000000', NULL, 1),
(958832, 112300, 24511, '<td valign="top">At first I''m thinking \"architecture\",  then scrolling down I noticed madame \"I have a fishing cane and I''m not afraid to use it\", who leads  me with her viewing direction to mister \"If I pretend to be asleep maybe she will get tired and forget\", until I glance back at madame \"If he really falls asleep I''m using my poking stick\", while mister \"I love it when she is so spirited\" returns madame''s \"If I didn''t love him so...\".  As old as civilisation love is captured by your choice of filter, subject and background.  Photo communicates a thousand words.  Like stone blocks long relationships have solid lasting foundations.  Upper space too huge but it is space that is being used as a tool to communicate.  Individuals tiny.  Great 8</td>', 'At first I''m thinking \"architecture\",  then scrolling down I noticed madame \"I have a fishing cane and I''m not afraid to use it\", who leads  me with her viewing direction to mister \"If I pretend to be asleep maybe she will get tired and forget\", until I glance back at madame \"If he really falls asleep I''m using my poking stick\", while mister \"I love it when she is so spirited\" returns madame''s \"If I didn''t love him so...\".  As old as civilisation love is captured by your choice of filter, subject and background.  Photo communicates a thousand words.  Like stone blocks long relationships have solid lasting foundations.  Upper space too huge but it is space that is being used as a tool to communicate.  Individuals tiny.  Great 8', '2004-10-14 02:08:25.000000', NULL, 1),
(958838, 112059, 19608, '<td valign="top">Good graphics - but the overexposure in the clouds hurts your image a lot.</td>', 'Good graphics - but the overexposure in the clouds hurts your image a lot.', '2004-10-14 02:13:16.000000', NULL, 1),
(958840, 112056, 24511, '<td valign="top">The angle of this shot is superb.  I found the foreground out of focus.  What I enjoyed exploring was the ceiling supports with varying degrees of wiring being reveiled.  So this is where some of our photos go in transit.  Thanks.</td>', 'The angle of this shot is superb.  I found the foreground out of focus.  What I enjoyed exploring was the ceiling supports with varying degrees of wiring being reveiled.  So this is where some of our photos go in transit.  Thanks.', '2004-10-14 02:14:24.000000', NULL, 1),
(958847, 112236, 24511, '<td valign="top">Do people still think that a way to a man''s heart is through his stomack?  Works for me.  Good idea, lovely angle and crisp photo.  Background very country goes with heart shape theme. Not my style but passed the test of Dpchallenge.  Thanks for the photo.<br/><br/><i>Message edited by author 2004-10-20 17:42:01.</i></td>', 'Do people still think that a way to a man''s heart is through his stomack?  Works for me.  Good idea, lovely angle and crisp photo.  Background very country goes with heart shape theme. Not my style but passed the test of Dpchallenge.  Thanks for the photo.', '2004-10-14 02:19:31.000000', '2004-10-20 18:42:01.000000', 1),
(958850, 111319, 24511, '<td valign="top">Body part used to communicate captured very well.  I find it very serene like a good listener (friend or shrink) that contrast with my last vote (image of someone giving me the finger).  The bad boy routine strikes me as more attractive, as much as I like a good listener.  Ear lobe very bright.  Thanks.</td>', 'Body part used to communicate captured very well.  I find it very serene like a good listener (friend or shrink) that contrast with my last vote (image of someone giving me the finger).  The bad boy routine strikes me as more attractive, as much as I like a good listener.  Ear lobe very bright.  Thanks.', '2004-10-14 02:22:36.000000', NULL, 1),
(958896, 112250, 5746, '<td valign="top">It''s like you didn''t have enough light, or maybe it looks like that on purpose. I would''ve prefer more composition elements. Too much for minimalistic picture, not enough for composition. 4.</td>', 'It''s like you didn''t have enough light, or maybe it looks like that on purpose. I would''ve prefer more composition elements. Too much for minimalistic picture, not enough for composition. 4.', '2004-10-14 04:40:50.000000', NULL, 1),
(958897, 111741, 5746, '<td valign="top">I don''t get it. Is the postman that is an object passing news and information? His leg is not very attractive, sorry :)</td>', 'I don''t get it. Is the postman that is an object passing news and information? His leg is not very attractive, sorry :)', '2004-10-14 04:41:56.000000', NULL, 1),
(958898, 112267, 5746, '<td valign="top">Metal snails? Looks great. It''s a wonderfull idea. I love the contrast between the snails and the pegasus on the envelope. Could have more contrast. 8.</td>', 'Metal snails? Looks great. It''s a wonderfull idea. I love the contrast between the snails and the pegasus on the envelope. Could have more contrast. 8.', '2004-10-14 04:43:48.000000', NULL, 1),
(958899, 111089, 27524, '<td valign="top">Good capture... specially the light spot over cross.</td>', 'Good capture... specially the light spot over cross.', '2004-10-14 04:44:25.000000', NULL, 1),
(958900, 112374, 5746, '<td valign="top">I thought os it too. The execution is good. I would''ve prefer the upper hand without blur, but I guess youd wanted to give the filling of movement, "passing" actually. I think if you cropped it more a bit and get rid of the cd in the background, it would make the message stronger and it would look great as an illustration in a computer magazine. 7.</td>', 'I thought os it too. The execution is good. I would''ve prefer the upper hand without blur, but I guess youd wanted to give the filling of movement, "passing" actually. I think if you cropped it more a bit and get rid of the cd in the background, it would make the message stronger and it would look great as an illustration in a computer magazine. 7.', '2004-10-14 04:45:57.000000', NULL, 1),
(958902, 111836, 27524, '<td valign="top">Good lights and focus.</td>', 'Good lights and focus.', '2004-10-14 04:48:27.000000', NULL, 1),
(958903, 111991, 5746, '<td valign="top">It is an original concept. You focused on the sparks in the center of the image. If you didn''t put "Morse" in the title, it would''ve been difficult to guess what it has to do with communication. Maybe different angle, more focus on the whole object would¹ve make the message clear. I like the idea of Morse alphabet. 7.</td>', 'It is an original concept. You focused on the sparks in the center of the image. If you didn''t put "Morse" in the title, it would''ve been difficult to guess what it has to do with communication. Maybe different angle, more focus on the whole object would¹ve make the message clear. I like the idea of Morse alphabet. 7.', '2004-10-14 04:50:02.000000', NULL, 1),
(958905, 112263, 5746, '<td valign="top">More colours or more sharpness would''ve make this picture more interesting I think. Now it''s just a tower... 5.</td>', 'More colours or more sharpness would''ve make this picture more interesting I think. Now it''s just a tower... 5.', '2004-10-14 04:51:12.000000', NULL, 1),
(958906, 112371, 5746, '<td valign="top">Fresh idea for book picture :) There is a story behind it. Great models and nice natural moment you''ve captured. 8.</td>', 'Fresh idea for book picture :) There is a story behind it. Great models and nice natural moment you''ve captured. 8.', '2004-10-14 04:53:22.000000', NULL, 1),
(958908, 112090, 9389, '<td valign="top">.. -. - . .-. . ... - .. -. --.<br/> <br/>-.-. .-.. . ...- . .-.   .. -.. . .-  .-.-.-</td>', '.. -. - . .-. . ... - .. -. --. -.-. .-.. . ...- . .-.   .. -.. . .-  .-.-.-', '2004-10-14 05:09:38.000000', NULL, 1),
(958930, 111625, 27482, '<td valign="top">Cool Idea!</td>', 'Cool Idea!', '2004-10-14 06:28:22.000000', NULL, 1),
(958932, 112059, 26679, '<td valign="top">There is an almost identical shot to this in this weeks Challenge, I prefer yours by a long shot. <br/> <br/>Its the background that does it for me, - its great.<br/>Did you explore submitting this off centre, I wondered whether that would provide an extra umph.<br/></td>', 'There is an almost identical shot to this in this weeks Challenge, I prefer yours by a long shot.  Its the background that does it for me, - its great.Did you explore submitting this off centre, I wondered whether that would provide an extra umph.', '2004-10-14 06:36:47.000000', NULL, 1),
(958934, 111839, 27482, '<td valign="top">I probably would have given it higher marks if I hadn´t already seen about 5 shots almost identical to this one.  Still a 6 though, keep up the good work.</td>', 'I probably would have given it higher marks if I hadn´t already seen about 5 shots almost identical to this one.  Still a 6 though, keep up the good work.', '2004-10-14 06:37:55.000000', NULL, 1),
(958935, 111836, 27482, '<td valign="top">Good shot, but I feel that you have either too much or too little empty space up in the right corner. 7</td>', 'Good shot, but I feel that you have either too much or too little empty space up in the right corner. 7', '2004-10-14 06:38:45.000000', NULL, 1),
(958937, 111535, 27482, '<td valign="top">The horribly overexposed backround draws way too much attention.  Also I probably would have given this a higher mark if I hadn´t seen about 10 other shots with cans and a string.  4</td>', 'The horribly overexposed backround draws way too much attention.  Also I probably would have given this a higher mark if I hadn´t seen about 10 other shots with cans and a string.  4', '2004-10-14 06:40:12.000000', NULL, 1),
(958938, 111991, 27482, '<td valign="top">Very cool idea!  Love how the sparks fly.  I still think however you could have done better with this idea, I have no idea on how they achieve this but I have seen several shots of sparks (from industrial shoots) that have the sparks more red/yellow so my guess is that the white balance could have been manipulated to achieve that effect.  Also the brown backround doesn´t help.  Anyway, great shot, wish I would have thought of it.  9 in my books.</td>', 'Very cool idea!  Love how the sparks fly.  I still think however you could have done better with this idea, I have no idea on how they achieve this but I have seen several shots of sparks (from industrial shoots) that have the sparks more red/yellow so my guess is that the white balance could have been manipulated to achieve that effect.  Also the brown backround doesn´t help.  Anyway, great shot, wish I would have thought of it.  9 in my books.', '2004-10-14 06:43:26.000000', NULL, 1),
(958939, 111590, 26679, '<td valign="top">2 separate observations.<br/> <br/>1. As a picture of two crabs, more impact could be achieved by sharpening up the focus and cropping to the right or left to move the focus of attention  off centre. Impact is also lost because the crabs are similar in shape colour and size to the background.<br/> <br/>2. For me this also strays a little too much off the theme of communication.<br/></td>', '2 separate observations. 1. As a picture of two crabs, more impact could be achieved by sharpening up the focus and cropping to the right or left to move the focus of attention  off centre. Impact is also lost because the crabs are similar in shape colour and size to the background. 2. For me this also strays a little too much off the theme of communication.', '2004-10-14 06:44:04.000000', NULL, 1),
(958942, 112468, 26679, '<td valign="top">I like the lighting and mood of this shot. Sepia really helps create the atmosphere. <br/> <br/>I know your title depicts the beginning of a story, but I wonder whether having few quill marks on the paper would have added to the scene.<br/></td>', 'I like the lighting and mood of this shot. Sepia really helps create the atmosphere.  I know your title depicts the beginning of a story, but I wonder whether having few quill marks on the paper would have added to the scene.', '2004-10-14 06:48:39.000000', NULL, 1),
(958959, 112176, 27767, '<td valign="top">I like this shot very much, though I feel a lot of other messages coming from it other than communication</td>', 'I like this shot very much, though I feel a lot of other messages coming from it other than communication', '2004-10-14 07:54:51.000000', NULL, 1),
(958962, 112265, 27767, '<td valign="top">Simple and solid composition. Great detail on envelope</td>', 'Simple and solid composition. Great detail on envelope', '2004-10-14 07:57:37.000000', NULL, 1),
(958965, 112389, 22781, '<td valign="top">Same 2U :-)<br/>8</td>', 'Same 2U :-)8', '2004-10-14 08:02:05.000000', NULL, 1),
(958966, 112317, 27767, '<td valign="top">Solid composition and vibrant color. Maybe could use an extra element to raise the shot to extraordinary.</td>', 'Solid composition and vibrant color. Maybe could use an extra element to raise the shot to extraordinary.', '2004-10-14 08:02:52.000000', NULL, 1),
(958970, 112006, 27767, '<td valign="top">I really like the depth of field in the shot and the colorful leaves at her feet.I''m having a hard time extracting a specific emotion or statement from her body language; longing maybe?</td>', 'I really like the depth of field in the shot and the colorful leaves at her feet.I''m having a hard time extracting a specific emotion or statement from her body language; longing maybe?', '2004-10-14 08:05:48.000000', NULL, 1),
(958971, 111600, 27767, '<td valign="top">Good message, though I wonder if different lighting would have given a fuller feeling shot.</td>', 'Good message, though I wonder if different lighting would have given a fuller feeling shot.', '2004-10-14 08:09:25.000000', NULL, 1),
(958972, 112435, 27767, '<td valign="top">I like the message a lot :)  Bottom left corner''s lack of focus is a tiny bit distracting.</td>', 'I like the message a lot :)  Bottom left corner''s lack of focus is a tiny bit distracting.', '2004-10-14 08:11:53.000000', NULL, 1),
(958973, 112322, 27767, '<td valign="top">Interesting composition and idea, though I don''t see a prominent message of "communication"</td>', 'Interesting composition and idea, though I don''t see a prominent message of "communication"', '2004-10-14 08:12:58.000000', NULL, 1),
(958974, 112010, 27767, '<td valign="top">Interesting message</td>', 'Interesting message', '2004-10-14 08:13:48.000000', NULL, 1),
(958976, 112297, 27767, '<td valign="top">I enjoy the depth of field and feather detail, though this cool focus might take the image''s message further away from communication</td>', 'I enjoy the depth of field and feather detail, though this cool focus might take the image''s message further away from communication', '2004-10-14 08:15:47.000000', NULL, 1),
(958978, 111392, 27767, '<td valign="top">Good message. Maybe a little more light or detail on the pen could make the image striking.</td>', 'Good message. Maybe a little more light or detail on the pen could make the image striking.', '2004-10-14 08:18:33.000000', NULL, 1),
(958980, 112183, 27767, '<td valign="top">I like this idea.  I also like the scene, though I wonder if the rule of thirds (2/3 sky, 1/3 land would be cool in this case) would have chopped out some of the foreground dirt, and given the lines a real zooming effect out to the horizon.</td>', 'I like this idea.  I also like the scene, though I wonder if the rule of thirds (2/3 sky, 1/3 land would be cool in this case) would have chopped out some of the foreground dirt, and given the lines a real zooming effect out to the horizon.', '2004-10-14 08:22:06.000000', NULL, 1),
(958981, 111140, 27767, '<td valign="top">provocative, though don''t like the message</td>', 'provocative, though don''t like the message', '2004-10-14 08:22:57.000000', NULL, 1),
(958982, 112157, 27767, '<td valign="top">Interesting setup, though the theme seems to have been lost a little</td>', 'Interesting setup, though the theme seems to have been lost a little', '2004-10-14 08:24:15.000000', NULL, 1),
(958986, 111690, 7889, '<td valign="top">Idea is good and the photo is ok, I think that if you had submitted in b&amp;w it would have given the photo more feeling etc. good luck</td>', 'Idea is good and the photo is ok, I think that if you had submitted in b&w it would have given the photo more feeling etc. good luck', '2004-10-14 08:29:27.000000', NULL, 1),
(958988, 112369, 7889, '<td valign="top">A good effort which would have benifited from a touch more contrast. I like the way you have only included part of the child''s face.<br/> <br/></td>', 'A good effort which would have benifited from a touch more contrast. I like the way you have only included part of the child''s face. ', '2004-10-14 08:31:14.000000', NULL, 1),
(958989, 111319, 27767, '<td valign="top">I like the focus on listening to a communication rather than transmitting the communication.</td>', 'I like the focus on listening to a communication rather than transmitting the communication.', '2004-10-14 08:35:15.000000', NULL, 1),
(958991, 111392, 7889, '<td valign="top">I think this would have been better if less of the pen was included, also there is something visible on the border above the e in Mercurty that distracts me.</td>', 'I think this would have been better if less of the pen was included, also there is something visible on the border above the e in Mercurty that distracts me.', '2004-10-14 08:36:22.000000', NULL, 1),
(958992, 112422, 27767, '<td valign="top">Coolest lighting I''ve seen yet for the tin cans idea. Very cool</td>', 'Coolest lighting I''ve seen yet for the tin cans idea. Very cool', '2004-10-14 08:37:03.000000', NULL, 1),
(958994, 111062, 27767, '<td valign="top">Cool shot, but I don''t see the theme supported in the image by itself.</td>', 'Cool shot, but I don''t see the theme supported in the image by itself.', '2004-10-14 08:37:45.000000', NULL, 1),
(958996, 112469, 27767, '<td valign="top">I like the shutter speed in this shot. Unique shot location</td>', 'I like the shutter speed in this shot. Unique shot location', '2004-10-14 08:38:59.000000', NULL, 1),
(958997, 112190, 27767, '<td valign="top">Not bad, maybe cropping out some of the ground would frame the subject a little better.</td>', 'Not bad, maybe cropping out some of the ground would frame the subject a little better.', '2004-10-14 08:42:38.000000', NULL, 1),
