(960308, 112508, 24674, '<td valign="top">mouth is distractingly wide open.</td>', 'mouth is distractingly wide open.', '2004-10-15 02:57:07.000000', NULL, 1),
(960309, 112409, 25217, '<td valign="top">The coloring is really nice, and I love the lighting here. The idea is great, and communicated excellently in the photo. I''d say the only thing really missing is a split-dress on the model with a more modern look on his left and an older look on his right.</td>', 'The coloring is really nice, and I love the lighting here. The idea is great, and communicated excellently in the photo. I''d say the only thing really missing is a split-dress on the model with a more modern look on his left and an older look on his right.', '2004-10-15 02:57:48.000000', NULL, 1),
