(960501, 112272, 23301, '<td valign="top">Great picture! Compositionally reflection is a bit off and breaks the symmetry. Also a slight imbalance between upper and lower parts of picture.</td>', 'Great picture! Compositionally reflection is a bit off and breaks the symmetry. Also a slight imbalance between upper and lower parts of picture.', '2004-10-15 09:25:01.000000', NULL, 1),
(960515, 112187, 24715, '<td valign="top">Great image. Colors and shadows work really well. But from the first glance the bottle did not look like a bottle to me. I guess it and its contents lack some definition. I am not marking down for that.</td>', 'Great image. Colors and shadows work really well. But from the first glance the bottle did not look like a bottle to me. I guess it and its contents lack some definition. I am not marking down for that.', '2004-10-15 09:58:55.000000', NULL, 1),
(960516, 112244, 8905, '<td valign="top">Good idea...!</td>', 'Good idea...!', '2004-10-15 09:59:01.000000', NULL, 1),
(960518, 112148, 24715, '<td valign="top">Very well composed shot. B&amp;W works well, definitley creates that retro look! Good luck!</td>', 'Very well composed shot. B&W works well, definitley creates that retro look! Good luck!', '2004-10-15 09:59:54.000000', NULL, 1),
(960523, 112000, 8905, '<td valign="top">hahhaha</td>', 'hahhaha', '2004-10-15 10:04:41.000000', NULL, 1),
