(960539, 112445, 16241, '<td valign="top">very nice</td>', 'very nice', '2004-10-15 10:31:10.000000', NULL, 1),
(960547, 112000, 10634, '<td valign="top">Very unique idea. Cropping it a little tighter might have made this more effective.</td>', 'Very unique idea. Cropping it a little tighter might have made this more effective.', '2004-10-15 10:58:39.000000', NULL, 1),
(960551, 112387, 10634, '<td valign="top">LOL  One of my pet peeves.</td>', 'LOL  One of my pet peeves.', '2004-10-15 11:03:56.000000', NULL, 1),
(960552, 112187, 10634, '<td valign="top">Beautiful colors and great idea. Focus on the bottle is a little soft for my taste.</td>', 'Beautiful colors and great idea. Focus on the bottle is a little soft for my taste.', '2004-10-15 11:08:12.000000', NULL, 1),
(960555, 112255, 10634, '<td valign="top">Excellent focus. However, the reflection near the neck of the bottle really ruins this shot.</td>', 'Excellent focus. However, the reflection near the neck of the bottle really ruins this shot.', '2004-10-15 11:10:56.000000', NULL, 1),
(960556, 112389, 10634, '<td valign="top">Very effective.</td>', 'Very effective.', '2004-10-15 11:12:11.000000', NULL, 1),
(960559, 111849, 10634, '<td valign="top">Nice shot. Like the perspective. The sun spots on the bottle detract from the overall image for me. Maybe taking the shot later in the day or at sunset would have added to the appeal of this shot.</td>', 'Nice shot. Like the perspective. The sun spots on the bottle detract from the overall image for me. Maybe taking the shot later in the day or at sunset would have added to the appeal of this shot.', '2004-10-15 11:14:08.000000', NULL, 1),
(960560, 112267, 10634, '<td valign="top">While there were a few shots of envelopes and/or postage, this one made me smile. Good focus and I like the tone.</td>', 'While there were a few shots of envelopes and/or postage, this one made me smile. Good focus and I like the tone.', '2004-10-15 11:15:47.000000', NULL, 1),
(960562, 112059, 10634, '<td valign="top">Like the perspective. The harsh colors in the sky give this a sci-fi feeling for me and really enhance the overall impact.</td>', 'Like the perspective. The harsh colors in the sky give this a sci-fi feeling for me and really enhance the overall impact.', '2004-10-15 11:17:18.000000', NULL, 1),
(960563, 111808, 10634, '<td valign="top">Good placement and perspective. Unique idea.</td>', 'Good placement and perspective. Unique idea.', '2004-10-15 11:19:11.000000', NULL, 1),
(960610, 112442, 1570, '<td valign="top">?</td>', '?', '2004-10-15 12:09:09.000000', NULL, 1),
(960634, 111843, 24065, '<td valign="top">I think your subject is right on-topic and very creative.  However, I would have scored it higher with a closer crop.</td>', 'I think your subject is right on-topic and very creative.  However, I would have scored it higher with a closer crop.', '2004-10-15 12:50:51.000000', NULL, 1),
(960813, 112358, 26756, '<td valign="top">I would have liked this more I think if the DOF weren''t so drastically shallow.  Visually I think it would have been better if at least that first button was in sharp focus.  Good angle and color.</td>', 'I would have liked this more I think if the DOF weren''t so drastically shallow.  Visually I think it would have been better if at least that first button was in sharp focus.  Good angle and color.', '2004-10-15 15:38:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(960819, 111656, 18368, '<td valign="top">Interesting treatment</td>', 'Interesting treatment', '2004-10-15 15:47:33.000000', NULL, 1),
(960822, 112304, 18368, '<td valign="top">Simple and interesting..</td>', 'Simple and interesting..', '2004-10-15 15:48:47.000000', NULL, 1),
(960830, 111309, 26679, '<td valign="top">Good name for the image. I feel that too much of the shot is out of focus, and this looses the impact for me.</td>', 'Good name for the image. I feel that too much of the shot is out of focus, and this looses the impact for me.', '2004-10-15 16:03:21.000000', NULL, 1),
(960831, 111490, 26679, '<td valign="top">Nice image of mum and child. A little sharper and this would be an excelent shot.</td>', 'Nice image of mum and child. A little sharper and this would be an excelent shot.', '2004-10-15 16:05:40.000000', NULL, 1),
(960841, 112003, 25218, '<td valign="top">This is great!</td>', 'This is great!', '2004-10-15 16:22:08.000000', NULL, 1),
(960842, 112374, 9295, '<td valign="top">I don''t normally care too much for pictures of CDs but this one is quite interesting. I like your different set up and perspective. The "burnt" orange color tones (that may or may not be "true" since my monitor tends to be a little dark) are cool and the blurred motion of the one hand works nicely.</td>', 'I don''t normally care too much for pictures of CDs but this one is quite interesting. I like your different set up and perspective. The "burnt" orange color tones (that may or may not be "true" since my monitor tends to be a little dark) are cool and the blurred motion of the one hand works nicely.', '2004-10-15 16:22:34.000000', NULL, 1),
(960845, 112228, 9295, '<td valign="top">The way the hand is placed made me think more of a blind person reading braille than a sign language for the deaf. Nevertheless, the picture looks a little blurry and I don''t care for the dark shadows on the white backdrop. I do like the composition and how you have the wrist in front of the border line. I also like the richness of the skin tones.</td>', 'The way the hand is placed made me think more of a blind person reading braille than a sign language for the deaf. Nevertheless, the picture looks a little blurry and I don''t care for the dark shadows on the white backdrop. I do like the composition and how you have the wrist in front of the border line. I also like the richness of the skin tones.', '2004-10-15 16:26:06.000000', NULL, 1),
(960852, 112483, 24486, '<td valign="top">I thought about using this concept myself &amp; looking at this example, I should of used it. This is a lovely photograph &amp; as a fan of B&amp;W I can say you made the right choice there too. Good luck with this photograph</td>', 'I thought about using this concept myself & looking at this example, I should of used it. This is a lovely photograph & as a fan of B&W I can say you made the right choice there too. Good luck with this photograph', '2004-10-15 16:32:45.000000', NULL, 1),
(960853, 112050, 16241, '<td valign="top">nice angle</td>', 'nice angle', '2004-10-15 16:35:13.000000', NULL, 1),
(960858, 112139, 9295, '<td valign="top">Love the shallow depth of field and the fact that you kept the label on the can. That adds so much to the picture and the red label balances the person''s red shirt nicely. This is my favorite of the string-and-can photos.</td>', 'Love the shallow depth of field and the fact that you kept the label on the can. That adds so much to the picture and the red label balances the person''s red shirt nicely. This is my favorite of the string-and-can photos.', '2004-10-15 16:37:09.000000', NULL, 1),
(960861, 112391, 9295, '<td valign="top">I love these little wooden guys. I rarely see a photo with them in the challenges that I really don''t like. The lighting in this one is nicely done to make the book the focal point while still enhancing the wooden man. Nice use of negative space as well.</td>', 'I love these little wooden guys. I rarely see a photo with them in the challenges that I really don''t like. The lighting in this one is nicely done to make the book the focal point while still enhancing the wooden man. Nice use of negative space as well.', '2004-10-15 16:39:25.000000', NULL, 1),
(960863, 112269, 25218, '<td valign="top">Nice sharp image - no noise! Love the title. Great "found" photo opportunity. The glare on the top is unfortunate - maybe it could have been cropped out?</td>', 'Nice sharp image - no noise! Love the title. Great "found" photo opportunity. The glare on the top is unfortunate - maybe it could have been cropped out?', '2004-10-15 16:40:00.000000', NULL, 1),
(960864, 111490, 25218, '<td valign="top">Very cute snapshot! It''s a bit blurry, but I love the look on the little guy''s face! And you gotta love IHOP!</td>', 'Very cute snapshot! It''s a bit blurry, but I love the look on the little guy''s face! And you gotta love IHOP!', '2004-10-15 16:40:49.000000', NULL, 1),
(960865, 111742, 9295, '<td valign="top">Although significant to the picture and necessary for lighting, the candle seems just a little TOO bright. Is there anything that can be done to soften it so that it doesn''t detract quite so much from the paper, which should be the focal point?</td>', 'Although significant to the picture and necessary for lighting, the candle seems just a little TOO bright. Is there anything that can be done to soften it so that it doesn''t detract quite so much from the paper, which should be the focal point?', '2004-10-15 16:42:05.000000', NULL, 1),
(960867, 112062, 25218, '<td valign="top">Great focus!</td>', 'Great focus!', '2004-10-15 16:42:31.000000', NULL, 1),
(960880, 112197, 9295, '<td valign="top">This is my favorite image of the challenge. Very powerful and thought-provoking. Excellent work. Good luck.</td>', 'This is my favorite image of the challenge. Very powerful and thought-provoking. Excellent work. Good luck.', '2004-10-15 16:58:52.000000', NULL, 1),
