(963550, 112157, 23251, '<td valign="top">Love the humor in this!  Congrats on thinking outside the box! Oh and the photo is well done too.</td>', 'Love the humor in this!  Congrats on thinking outside the box! Oh and the photo is well done too.', '2004-10-18 07:04:46.000000', NULL, 1),
(963553, 112197, 23251, '<td valign="top">Unfortunatly its very busy, so my eyes are travelling all over the frame.  Pity as I really like the idea.  Maybe a shallow DOF would have blured the backgroung and helped. Nice try.</td>', 'Unfortunatly its very busy, so my eyes are travelling all over the frame.  Pity as I really like the idea.  Maybe a shallow DOF would have blured the backgroung and helped. Nice try.', '2004-10-18 07:11:41.000000', NULL, 1),
(963560, 112119, 23251, '<td valign="top">I really like this shot and idea, only 1 thing puts me off and I think it could be part of the glasses at the top right hand side.  Its very distracting.  Lovely idea though.</td>', 'I really like this shot and idea, only 1 thing puts me off and I think it could be part of the glasses at the top right hand side.  Its very distracting.  Lovely idea though.', '2004-10-18 07:23:23.000000', NULL, 1),
(963573, 112148, 23251, '<td valign="top">Nice idea but your editing has discoloured the teeth, I find that kinda draws my attention instead of looking at the smile.  Great idea tough.</td>', 'Nice idea but your editing has discoloured the teeth, I find that kinda draws my attention instead of looking at the smile.  Great idea tough.', '2004-10-18 07:47:38.000000', NULL, 1),
(963574, 111649, 23251, '<td valign="top">Far to busy with out a clear focal point.</td>', 'Far to busy with out a clear focal point.', '2004-10-18 07:48:12.000000', NULL, 1),
