(963774, 112230, 25679, '<td valign="top">This would be better if taken at night.</td>', 'This would be better if taken at night.', '2004-10-18 12:34:17.000000', NULL, 1),
(964036, 111472, 20754, '<td valign="top">Love the composition and mood of this shot...the strong diagnals and fog are a definite plus...i wish the dense blotch of fog covering the apex wasn''t there or was at least a bit wispier, but we all can''t be mother nature....great job, it is my highest rated photo! :)</td>', 'Love the composition and mood of this shot...the strong diagnals and fog are a definite plus...i wish the dense blotch of fog covering the apex wasn''t there or was at least a bit wispier, but we all can''t be mother nature....great job, it is my highest rated photo! :)', '2004-10-18 16:37:29.000000', NULL, 1),
(964040, 112422, 20754, '<td valign="top">Love the color, composition and refractions off the cans...excellent textures and lighting...one of my faves of the challenge...great work!</td>', 'Love the color, composition and refractions off the cans...excellent textures and lighting...one of my faves of the challenge...great work!', '2004-10-18 16:38:41.000000', NULL, 1),
(964048, 112409, 20754, '<td valign="top">Of all the numerous ''telecan'' shots this is one of my faves...i only wish the light source was a bit higher and more towards the front so that the harsh shadows didn''t go across the face and body sideways and perhaps the lighting can be diffused more...otherwise nice concept, composition and color!</td>', 'Of all the numerous ''telecan'' shots this is one of my faves...i only wish the light source was a bit higher and more towards the front so that the harsh shadows didn''t go across the face and body sideways and perhaps the lighting can be diffused more...otherwise nice concept, composition and color!', '2004-10-18 16:41:44.000000', NULL, 1),
(964060, 112119, 20754, '<td valign="top">great job here...this is one of my faves of the challenge...colors/angled composition is great ..the mic is lit wonderfully...i''m not too fond of the lighting of the singer though...the bright somewhat overexposed flesh tones competes too much with the mic and detracts from the image...also the object coming from the top of the face (i''m assuming they are glasses) is kind of a detraction as well because it is hard to see what they are and almost looks like a clone mishap..no real point of having it in the shot unless they are more prominent in the cropping...otherwise great job...this is one of my high scores!</td>', 'great job here...this is one of my faves of the challenge...colors/angled composition is great ..the mic is lit wonderfully...i''m not too fond of the lighting of the singer though...the bright somewhat overexposed flesh tones competes too much with the mic and detracts from the image...also the object coming from the top of the face (i''m assuming they are glasses) is kind of a detraction as well because it is hard to see what they are and almost looks like a clone mishap..no real point of having it in the shot unless they are more prominent in the cropping...otherwise great job...this is one of my high scores!', '2004-10-18 16:47:10.000000', NULL, 1),
(964062, 112198, 20754, '<td valign="top">a really well composed and well exposed night shot...great job!</td>', 'a really well composed and well exposed night shot...great job!', '2004-10-18 16:48:09.000000', NULL, 1),
(964084, 112508, 20754, '<td valign="top">I really love the warm tones of this shot and the lighting is fine but the balance of the composition really does not work for me at least not in this specific cropping...otherwise a great shot!</td>', 'I really love the warm tones of this shot and the lighting is fine but the balance of the composition really does not work for me at least not in this specific cropping...otherwise a great shot!', '2004-10-18 16:53:20.000000', NULL, 1),
