(964532, 112198, 25787, '<td valign="top">I think the background constellation is Taurus.  I see the pleides just above the right side of the dish, and the heyedes above the left center of the dish.  Very nice.</td>', 'I think the background constellation is Taurus.  I see the pleides just above the right side of the dish, and the heyedes above the left center of the dish.  Very nice.', '2004-10-18 22:47:43.000000', NULL, 1),
(964536, 111757, 6667, '<td valign="top">Wow,  And here I am reading volume 17 of O''Brian''s Master and Commander.  Beautiful clear shot of the spars and rigging.  What ship and "Where away?"  Looks like a lot of new lines on her.  I have to ask though . . . what is the connection to communication?  Were there no signal flags to fly? BOL</td>', 'Wow,  And here I am reading volume 17 of O''Brian''s Master and Commander.  Beautiful clear shot of the spars and rigging.  What ship and "Where away?"  Looks like a lot of new lines on her.  I have to ask though . . . what is the connection to communication?  Were there no signal flags to fly? BOL', '2004-10-18 22:49:06.000000', NULL, 1),
(964539, 110883, 6667, '<td valign="top">Nicely done.  I am surprised there were so few signs entered,  BOL  Love the rich color tones.  8</td>', 'Nicely done.  I am surprised there were so few signs entered,  BOL  Love the rich color tones.  8', '2004-10-18 22:52:18.000000', NULL, 1),
(964571, 111817, 27933, '<td valign="top">witty, the best so far</td>', 'witty, the best so far', '2004-10-18 23:09:40.000000', NULL, 1),
