(964591, 112422, 28144, '<td valign="top">I love the lighting, very modern looking. nice composition.</td>', 'I love the lighting, very modern looking. nice composition.', '2004-10-18 23:24:51.000000', NULL, 1),
(964756, 111004, 24486, '<td valign="top">An extra point for getting a flag in to the photograph that wasnt American. :)</td>', 'An extra point for getting a flag in to the photograph that wasnt American. :)', '2004-10-19 01:40:00.000000', NULL, 1),
(964901, 112236, 25234, '<td valign="top">wooow~ very cute!</td>', 'wooow~ very cute!', '2004-10-19 04:48:06.000000', NULL, 1),
(964904, 112508, 25234, '<td valign="top">I''m sorry if my comment is bad, but I got the feeling that this picture is too close..  I can feel that my comfort..  It would be nice if the object is liter bid farter.. but I love the idea of the pic</td>', 'I''m sorry if my comment is bad, but I got the feeling that this picture is too close..  I can feel that my comfort..  It would be nice if the object is liter bid farter.. but I love the idea of the pic', '2004-10-19 04:51:20.000000', NULL, 1),
