(964908, 112340, 25234, '<td valign="top">LOL!..</td>', 'LOL!..', '2004-10-19 04:54:19.000000', NULL, 1),
(964912, 112368, 25234, '<td valign="top">I gave you 10, for your creative!</td>', 'I gave you 10, for your creative!', '2004-10-19 04:57:02.000000', NULL, 1),
(964969, 111492, 27767, '<td valign="top">I like the abstract feel of this shot, and the narrow range of colors.</td>', 'I like the abstract feel of this shot, and the narrow range of colors.', '2004-10-19 07:42:34.000000', NULL, 1),
(964971, 112420, 27767, '<td valign="top">Good idea.  I wonder if using a shallow depth of field would have helped eliminate the slightly distracting background to give more focus to your subject.</td>', 'Good idea.  I wonder if using a shallow depth of field would have helped eliminate the slightly distracting background to give more focus to your subject.', '2004-10-19 07:44:11.000000', NULL, 1),
(964972, 112443, 23251, '<td valign="top">I would have liked to seethe text and the top of the pen in focus rather than the top of the pen.  Nice idea though.</td>', 'I would have liked to seethe text and the top of the pen in focus rather than the top of the pen.  Nice idea though.', '2004-10-19 07:44:20.000000', NULL, 1),
(964973, 111861, 23251, '<td valign="top">Sorry but that has nothing to do with communication.</td>', 'Sorry but that has nothing to do with communication.', '2004-10-19 07:45:21.000000', NULL, 1),
(964974, 111417, 27767, '<td valign="top">Interesting scene, but I''m having trouble finding the "communication" theme in this shot</td>', 'Interesting scene, but I''m having trouble finding the "communication" theme in this shot', '2004-10-19 07:45:37.000000', NULL, 1),
(964977, 112296, 27767, '<td valign="top">In line with the challenge, though I wonder if a different (less standard) composition could have given this shot a unique feel. Focus of picture draws to camera lens, which is dead center in the "foul zone" which doesn''t leave too much of a natural path for the eye to follow. Using the rule of thirds might give the shot some more energy</td>', 'In line with the challenge, though I wonder if a different (less standard) composition could have given this shot a unique feel. Focus of picture draws to camera lens, which is dead center in the "foul zone" which doesn''t leave too much of a natural path for the eye to follow. Using the rule of thirds might give the shot some more energy', '2004-10-19 07:51:27.000000', NULL, 1),
(964978, 110883, 27767, '<td valign="top">Awesome lighting and great symetrical feel.</td>', 'Awesome lighting and great symetrical feel.', '2004-10-19 07:52:25.000000', NULL, 1),
(964979, 112056, 27767, '<td valign="top">Good idea, though the shot feels pretty busy. Maybe more selective focus or depth of field could communicate your message more clearly.</td>', 'Good idea, though the shot feels pretty busy. Maybe more selective focus or depth of field could communicate your message more clearly.', '2004-10-19 07:54:10.000000', NULL, 1),
(964980, 112400, 27767, '<td valign="top">I like the sign language idea and the border color. Maybe a translation of the sign in the title could help the viewer feel more of a connection.</td>', 'I like the sign language idea and the border color. Maybe a translation of the sign in the title could help the viewer feel more of a connection.', '2004-10-19 07:56:09.000000', NULL, 1),
(964982, 111817, 27767, '<td valign="top">Connection with challenge is hard to see from the picture alone.  Someone shouting and trying to "shoo" them off the boat could have drove home the challenge theme (and added some humor because of the "Mi Casa" name on the boat).</td>', 'Connection with challenge is hard to see from the picture alone.  Someone shouting and trying to "shoo" them off the boat could have drove home the challenge theme (and added some humor because of the "Mi Casa" name on the boat).', '2004-10-19 07:59:25.000000', NULL, 1),
(964983, 111490, 23251, '<td valign="top">Just a little oof...  Same as its a great moment to capture.</td>', 'Just a little oof...  Same as its a great moment to capture.', '2004-10-19 08:00:48.000000', NULL, 1),
(964984, 111658, 27767, '<td valign="top">Very very cool flowers, and greate depth of field.  The only thing I feel is that the message of communication is mostly in the title instead of the photo.</td>', 'Very very cool flowers, and greate depth of field.  The only thing I feel is that the message of communication is mostly in the title instead of the photo.', '2004-10-19 08:08:31.000000', NULL, 1),
(964987, 111811, 27767, '<td valign="top">Great idea. I am just having a hard time finding the natural focus of the photo.</td>', 'Great idea. I am just having a hard time finding the natural focus of the photo.', '2004-10-19 08:10:55.000000', NULL, 1),
(964988, 112155, 27767, '<td valign="top">Ooo, I like the different exposures and the message</td>', 'Ooo, I like the different exposures and the message', '2004-10-19 08:12:48.000000', NULL, 1),
(964989, 112284, 27767, '<td valign="top">Maybe if the speaker box was included the "communication" challenge theme would be more evident</td>', 'Maybe if the speaker box was included the "communication" challenge theme would be more evident', '2004-10-19 08:14:15.000000', NULL, 1),
(964990, 112513, 27767, '<td valign="top">I like the long exposure a lot, and "communication" is very clear</td>', 'I like the long exposure a lot, and "communication" is very clear', '2004-10-19 08:16:09.000000', NULL, 1),
(964993, 111398, 27767, '<td valign="top">Very creative and original shot of a tower. Very nice reflections and reeds in the foreground.</td>', 'Very creative and original shot of a tower. Very nice reflections and reeds in the foreground.', '2004-10-19 08:18:01.000000', NULL, 1),
(964994, 112029, 27767, '<td valign="top">Strong "communication" message. Maybe a little funky cropping or focus or depth of field would really make this shot stand out.</td>', 'Strong "communication" message. Maybe a little funky cropping or focus or depth of field would really make this shot stand out.', '2004-10-19 08:19:54.000000', NULL, 1),
(964995, 111625, 27767, '<td valign="top">very creative idea</td>', 'very creative idea', '2004-10-19 08:22:20.000000', NULL, 1),
(964999, 112331, 27767, '<td valign="top">I like the curls on the corners of the sheet of paper and the lack of color. I''m wondering if an off-center composition or some communication themed background details could deliver a stronger message?</td>', 'I like the curls on the corners of the sheet of paper and the lack of color. I''m wondering if an off-center composition or some communication themed background details could deliver a stronger message?', '2004-10-19 08:24:58.000000', NULL, 1),
(965000, 111994, 27767, '<td valign="top">I love the expression of the person on the right :)  I think an even stronger shot might be composed with just the guy on the right with the string moving off the left side of the picture (without showing the other cup or person).  That would leave some mystery and let the viewer''s mind make up what the 2nd person was doing.</td>', 'I love the expression of the person on the right :)  I think an even stronger shot might be composed with just the guy on the right with the string moving off the left side of the picture (without showing the other cup or person).  That would leave some mystery and let the viewer''s mind make up what the 2nd person was doing.', '2004-10-19 08:29:26.000000', NULL, 1),
(965002, 111870, 27767, '<td valign="top">Great composition using the rule of thirds. Teaching is also a good subject to show communication.</td>', 'Great composition using the rule of thirds. Teaching is also a good subject to show communication.', '2004-10-19 08:30:30.000000', NULL, 1),
