(966365, 111443, 5585, '<td valign="top">Just My Opinion....but this Photo...got robbed...very low scored for the Quality presented...it''s a shame.... just wanted you to know</td>', 'Just My Opinion....but this Photo...got robbed...very low scored for the Quality presented...it''s a shame.... just wanted you to know', '2004-10-20 04:40:36.000000', NULL, 0),
(966367, 112331, 27524, '<td valign="top">Thanks everybody for voting and comenting...<br/>Im actually bit surprised cuz i was hanging on 4,9 for long time but ended up higher :)<br/>It was my first try for challenge and made not in best conditions but Im glad that still lot of people gave me good points... that they saw there the same as I did.</td>', 'Thanks everybody for voting and comenting...Im actually bit surprised cuz i was hanging on 4,9 for long time but ended up higher :)It was my first try for challenge and made not in best conditions but Im glad that still lot of people gave me good points... that they saw there the same as I did.', '2004-10-20 04:43:02.000000', NULL, 0),
(966369, 112198, 21576, '<td valign="top">Congratulations, a well deserved blue.</td>', 'Congratulations, a well deserved blue.', '2004-10-20 04:53:51.000000', NULL, 0),
(966370, 112198, 21714, '<td valign="top">Congratulations on the Blue. Keep up the great work coming. It''s highly enjoyable.</td>', 'Congratulations on the Blue. Keep up the great work coming. It''s highly enjoyable.', '2004-10-20 04:54:21.000000', NULL, 0),
(966371, 112436, 5585, '<td valign="top">Ya know this deserves a comment....great Stock Photo... Great DOF....ya done good....</td>', 'Ya know this deserves a comment....great Stock Photo... Great DOF....ya done good....', '2004-10-20 04:54:58.000000', NULL, 0),
(966372, 112468, 21714, '<td valign="top">Congratulations on the Ribbon. Your hard work paid off. (SMILE) Keep it up.</td>', 'Congratulations on the Ribbon. Your hard work paid off. (SMILE) Keep it up.', '2004-10-20 04:55:43.000000', NULL, 0),
(966373, 111492, 21714, '<td valign="top">Congratulations on the Ribbon. Wonderful perspective, great vision. Keep it up.</td>', 'Congratulations on the Ribbon. Wonderful perspective, great vision. Keep it up.', '2004-10-20 04:56:46.000000', NULL, 0),
(966377, 112398, 5585, '<td valign="top">The best of the "Tin Can"....</td>', 'The best of the "Tin Can"....', '2004-10-20 04:58:26.000000', NULL, 0),
(966378, 112468, 21576, '<td valign="top">Congratulations on your ribbon, one thing I thought was strange when I saw this shot is that you can''t write left handed with a quill without making a mess.  I still like it though well done.</td>', 'Congratulations on your ribbon, one thing I thought was strange when I saw this shot is that you can''t write left handed with a quill without making a mess.  I still like it though well done.', '2004-10-20 04:59:23.000000', NULL, 0),
(966384, 111492, 1368, '<td valign="top">Congrats man :D</td>', 'Congrats man :D', '2004-10-20 05:15:48.000000', NULL, 0),
(966386, 112468, 26903, '<td valign="top">A really nice shot, excellent light/shadows and very good composition. Congratulations on your ribbon.</td>', 'A really nice shot, excellent light/shadows and very good composition. Congratulations on your ribbon.', '2004-10-20 05:24:22.000000', NULL, 0),
(966388, 112090, 16493, '<td valign="top">...---... ...---... ...---...<br/>Very nice comment, wish I had a code book.<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by geofffox:</b></div><hr/><i> .. -. - . .-. . ... - .. -. --.<br/> <br/>-.-. .-.. . ...- . .-.   .. -.. . .-  .-.-.- </i></td></tr></table><br/><br/><i>Message edited by author 2004-10-20 04:26:39.</i></td>', '...---... ...---... ...---...Very nice comment, wish I had a code book. Originally posted by geofffox: .. -. - . .-. . ... - .. -. --. -.-. .-.. . ...- . .-.   .. -.. . .-  .-.-.- ', '2004-10-20 05:26:16.000000', '2004-10-20 05:26:39.000000', 0),
(966390, 112090, 93, '<td valign="top">I think I might be one of the first.. if not *the* first.. person on DPC to ever get a comment written exclusively in morse code :)<br/> <br/>Thank you geoffox! :)<br/> <br/>Thank you to everyone that took the time to comment.  This scored much higher than anticipated, and I''m very happy with the outcome.  Subliminal messaging *does* work! (to a point. haha).<br/> <br/></td>', 'I think I might be one of the first.. if not *the* first.. person on DPC to ever get a comment written exclusively in morse code :) Thank you geoffox! :) Thank you to everyone that took the time to comment.  This scored much higher than anticipated, and I''m very happy with the outcome.  Subliminal messaging *does* work! (to a point. haha). ', '2004-10-20 05:33:30.000000', NULL, 0),
(966398, 111542, 19035, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by graphicfunk:</b></div><hr/><i> Great work here. By far your best image and you are certainly moving in the right direction. My warm congratulations on your top 20 finish. To get an even higher score avoid borders. I like them, but there is shool everywhere that hate them on principle. Regardless, rejoyce. Good job. </i></td></tr></table><i></i> <br/>Thanks for your great comments, what was I thinking with this ugly border?  Oh well, Im learning, wont do it next time...heh.  Thanks again everyone!</td>', 'Originally posted by graphicfunk: Great work here. By far your best image and you are certainly moving in the right direction. My warm congratulations on your top 20 finish. To get an even higher score avoid borders. I like them, but there is shool everywhere that hate them on principle. Regardless, rejoyce. Good job.  Thanks for your great comments, what was I thinking with this ugly border?  Oh well, Im learning, wont do it next time...heh.  Thanks again everyone!', '2004-10-20 05:54:32.000000', NULL, 0),
(966405, 112300, 14603, '<td valign="top">This shot got my highest score in the challenge and I really thought it would do much better.<br/></td>', 'This shot got my highest score in the challenge and I really thought it would do much better.', '2004-10-20 06:03:17.000000', NULL, 0),
(966409, 112462, 14603, '<td valign="top">In my opinion, this was a better picture than your score would suggest.<br/>There are a few grainy artifacts in the coloured sections which may have been the reason some voters scored you down, but overall, nicely presented and worthy of a much higher finish.</td>', 'In my opinion, this was a better picture than your score would suggest.There are a few grainy artifacts in the coloured sections which may have been the reason some voters scored you down, but overall, nicely presented and worthy of a much higher finish.', '2004-10-20 06:11:37.000000', NULL, 0),
(966413, 112198, 14603, '<td valign="top">Great image and worthy ribbon winner.<br/>Congratulations</td>', 'Great image and worthy ribbon winner.Congratulations', '2004-10-20 06:17:59.000000', NULL, 0),
(966414, 112197, 19035, '<td valign="top">You were robbed on this one, excellent shot.  I gave you an 8, maybe should have gone higher.  Great job!</td>', 'You were robbed on this one, excellent shot.  I gave you an 8, maybe should have gone higher.  Great job!', '2004-10-20 06:19:32.000000', NULL, 0),
(966415, 111699, 26246, '<td valign="top">Thank you all.<br/>Actually it was not fog but clouds as it''s the top of the highest mount over the city of Genova, north west coast of Italy.<br/>I did''n streightened it to let horizontal the generators house. I tought it could show more depth to let it untouched.<br/>The light and atmosphere was really unnatural, buzzing and freezing too.<br/>Ciao,<br/>Katranka</td>', 'Thank you all.Actually it was not fog but clouds as it''s the top of the highest mount over the city of Genova, north west coast of Italy.I did''n streightened it to let horizontal the generators house. I tought it could show more depth to let it untouched.The light and atmosphere was really unnatural, buzzing and freezing too.Ciao,Katranka', '2004-10-20 06:19:41.000000', NULL, 0),
(966416, 112468, 14603, '<td valign="top">Great shot for this challenge and very well presented.<br/>Congratulations.</td>', 'Great shot for this challenge and very well presented.Congratulations.', '2004-10-20 06:21:02.000000', NULL, 0),
(966418, 112389, 19035, '<td valign="top">I gave you an 8, dont worry about the hypocrits, you have an excellent photograph that makes a strong  statement and has a lot of emotion behind it, great job.</td>', 'I gave you an 8, dont worry about the hypocrits, you have an excellent photograph that makes a strong  statement and has a lot of emotion behind it, great job.', '2004-10-20 06:23:53.000000', NULL, 0),
(966420, 112148, 10390, '<td valign="top">Congrats on your 12th place finish. This is a very good shot and even better than some of the photos that ended higher in the challenge imo.</td>', 'Congrats on your 12th place finish. This is a very good shot and even better than some of the photos that ended higher in the challenge imo.', '2004-10-20 06:25:52.000000', NULL, 0),
(966423, 111492, 14603, '<td valign="top">Congratulations Thamer.<br/>Good to see your incredible consistency paying off with a ribbon.<br/>I am certain it won`t be long before I`m congratulating you again.</td>', 'Congratulations Thamer.Good to see your incredible consistency paying off with a ribbon.I am certain it won`t be long before I`m congratulating you again.', '2004-10-20 06:30:06.000000', NULL, 0),
(966433, 111750, 16147, '<td valign="top">Well, 97th for my first Challenge - thanks to all those who voted! :)</td>', 'Well, 97th for my first Challenge - thanks to all those who voted! :)', '2004-10-20 06:35:31.000000', NULL, 0),
(966440, 112468, 7810, '<td valign="top">Congrats on your first ribbon!!! <br/>Nice image <br/> <br/>Coley</td>', 'Congrats on your first ribbon!!! Nice image  Coley', '2004-10-20 06:38:10.000000', NULL, 0),
(966452, 112296, 8721, '<td valign="top">Well this being my first challenge entry I would like to thank those who took time to voted for my photo and specially those who gave comments.  I hadn´t realised how much I means to get somones opinion on your work.  Most of the comments I got were about my photo not being in focus but that''s actually what I was going for.  I wanted the photos in the back to be in focus.  But after getting those comments and looking harder on my entry. . . I don''t know what I was thinking!  Of course the camera and the whole pic had to be in focus but I''m still learning and I''m sure I''ll do it better in next challenge :)</td>', 'Well this being my first challenge entry I would like to thank those who took time to voted for my photo and specially those who gave comments.  I hadn´t realised how much I means to get somones opinion on your work.  Most of the comments I got were about my photo not being in focus but that''s actually what I was going for.  I wanted the photos in the back to be in focus.  But after getting those comments and looking harder on my entry. . . I don''t know what I was thinking!  Of course the camera and the whole pic had to be in focus but I''m still learning and I''m sure I''ll do it better in next challenge :)', '2004-10-20 06:45:21.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(966467, 111398, 23478, '<td valign="top">Well, another middle of the road score.  What I was trying to do here was show how this radio tower is dominating the small town, and hence, how communications dominate our lives.  Too much of a stretch I guess!  Thanks for all of the comments, it was fun shooting this photo.</td>', 'Well, another middle of the road score.  What I was trying to do here was show how this radio tower is dominating the small town, and hence, how communications dominate our lives.  Too much of a stretch I guess!  Thanks for all of the comments, it was fun shooting this photo.', '2004-10-20 06:56:01.000000', NULL, 0),
(966474, 111492, 9913, '<td valign="top">man you finally got a ribbon c," ) <br/>Congrats:D</td>', 'man you finally got a ribbon c," ) Congrats:D', '2004-10-20 07:01:10.000000', NULL, 0),
(966521, 112468, 23356, '<td valign="top">Congratulations, we were obviously on the same wave length (I think).  You achieved the look I was after, although if I could be a tiny bit picky, I think one or two words on the paper might have improved it but that''s only my opinion.  well done, great photo.  (I gave it a 7 by the way.)</td>', 'Congratulations, we were obviously on the same wave length (I think).  You achieved the look I was after, although if I could be a tiny bit picky, I think one or two words on the paper might have improved it but that''s only my opinion.  well done, great photo.  (I gave it a 7 by the way.)', '2004-10-20 08:30:32.000000', NULL, 0),
(966527, 112197, 5746, '<td valign="top">Congratulations on the top 20. It''s a pity it didn''t end higher.<br/>Great shot and inetersting interpretation. Maybe it awasn''t easy enough for people to get it?</td>', 'Congratulations on the top 20. It''s a pity it didn''t end higher.Great shot and inetersting interpretation. Maybe it awasn''t easy enough for people to get it?', '2004-10-20 08:36:11.000000', NULL, 0),
